"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings.

    Handles quoted fields, escaped quotes (""), commas and newlines inside
    quoted fields, CRLF line endings, and a missing trailing newline.
    """
    rows: list[list[str]] = []
    field: list[str] = []
    row: list[str] = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ",":
                row.append("".join(field))
                field = []
            elif ch == "\n":
                row.append("".join(field))
                field = []
                rows.append(row)
                row = []
            elif ch == "\r":
                row.append("".join(field))
                field = []
                rows.append(row)
                row = []
                if i + 1 < n and text[i + 1] == "\n":
                    i += 1
            else:
                field.append(ch)
        i += 1

    # Flush the final record if the text does not end with a line break.
    if field or row:
        row.append("".join(field))
        rows.append(row)

    return rows

