Standard sliding window using a frequency counter. O(n) via collections.Counter or a dict.

Implementation:

```python
from collections import Counter

def window_distinct_counts(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    n = len(values)
    if k > n:
        return []
    freq = {}
    distinct = 0
    for i in range(k):
        v = values[i]
        if freq.get(v, 0) == 0:
            distinct += 1
        freq[v] = freq.get(v, 0) + 1
    counts = [distinct]
    for start in range(1, n - k + 1):
        out_v = values[start - 1]
        if freq[out_v] == 1:
            del freq[out_v]
            distinct -= 1
        else:
            freq[out_v] -= 1
        in_v = values[start + k - 1]
        if freq.get(in_v, 0) == 0:
            distinct += 1
        freq[in_v] = freq.get(in_v, 0) + 1
        counts.append(distinct)
    return counts
```

